type Queue struct {
    mu   sync.Mutex
    cond *sync.Cond
    buf  []Msg
    cap  int
}
func (q *Queue) Put(m Msg) {
    q.mu.Lock(); defer q.mu.Unlock()
    for len(q.buf) == q.cap { q.cond.Wait() }   // predicate loop
    q.buf = append(q.buf, m)
    q.cond.Broadcast()
}

