type Queue struct{ ops chan func(*state) }
func NewQueue() *Queue { q := &Queue{ops: make(chan func(*state))}; go q.run(); return q }
func (q *Queue) Put(m Msg) {
    done := make(chan struct{})
    q.ops <- func(s *state) { s.push(m); close(done) }
    <-done                       // blocks until the owner applied the call
}
func (q *Queue) run() { s := &state{}; for f := range q.ops { f(s) } }
